-- State transitions declared for SecurityEvent (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.security_events_resolved_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."resolved" IS DISTINCT FROM OLD."resolved" AND NOT (
           (COALESCE(OLD."resolved"::text, ''), COALESCE(NEW."resolved"::text, '')) IN (('false', 'true'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: security_events.resolved % -> %', OLD."resolved", NEW."resolved";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS security_events_resolved_transition_check ON sapiens.security_events;
CREATE TRIGGER security_events_resolved_transition_check
    BEFORE UPDATE OF "resolved" ON sapiens.security_events
    FOR EACH ROW EXECUTE FUNCTION sapiens.security_events_resolved_transition_check();
